import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import { Children } from 'react'
import type { HTMLAttributes, ReactNode } from 'react'
import { Avatar } from '../avatar/avatar'
import styles from './avatar-group.module.css'

export interface AvatarGroupLabels {
  /** Accessible label for the +N overflow chip. */
  more?: (count: number) => string
}

export interface AvatarGroupProps extends HTMLAttributes<HTMLDivElement> {
  /** Cap the number of visible avatars; the rest collapse into a +N chip. */
  max?: number
  /** Override the total count used for the +N chip (when more exist than rendered). */
  total?: number
  /**
   * Spacing between items.
   *
   * @defaultValue `md`
   * @see the component manifest
   */
  spacing?: 'sm' | 'md' | 'lg'
  /**
   * When true, lays the avatars out in a grid instead of an overlapping stack.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  isGrid?: boolean
  labels?: AvatarGroupLabels
  /** The <Avatar> children. */
  children?: ReactNode
}

/** Overlapping stack of avatars with a `max` cap and an i18n-labelled +N overflow chip. */
export function AvatarGroup({
  max,
  total,
  spacing = 'md',
  isGrid = false,
  labels,
  className,
  children,
  ...rest
}: AvatarGroupProps) {
  const items = Children.toArray(children)
  const visible = max != null ? items.slice(0, max) : items
  const count = total ?? items.length
  const overflow = count - visible.length
  const moreLabel = labels?.more?.(overflow) ?? t(builtin.avatarGroup.more, { count: overflow })

  return (
    <div
      role="group"
      data-spacing={spacing}
      data-grid={isGrid || undefined}
      className={cn(styles['group'], className)}
      {...rest}
    >
      {visible}
      {overflow > 0 && (
        <Avatar className={styles['overflow']} fallback={`+${overflow}`} aria-label={moreLabel} />
      )}
    </div>
  )
}

@layer cascivo.component {
  .group {
    display: inline-flex;
    align-items: center;

    /* Overlapping row: each avatar after the first slides under the previous,
       with a ring (matched to the surface) to keep them visually separate. */
    & > * {
      box-shadow: 0 0 0 2px var(--cascivo-color-surface);
    }

    &:not([data-grid]) > *:not(:first-child) {
      margin-inline-start: var(--overlap, -0.5rem);
    }

    &[data-spacing='sm'] {
      --overlap: -0.25rem;
    }
    &[data-spacing='md'] {
      --overlap: -0.5rem;
    }
    &[data-spacing='lg'] {
      --overlap: -0.75rem;
    }

    /* Grid mode: wrap into rows with positive gaps, no overlap. */
    &[data-grid] {
      display: inline-grid;
      grid-template-columns: repeat(auto-fit, minmax(0, max-content));
      gap: var(--cascivo-space-2);
    }
  }

  .overflow {
    color: var(--cascivo-color-text-muted);
    font-size: var(--cascivo-text-xs);
    font-weight: var(--cascivo-font-medium);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'AvatarGroup',
  description: 'Overlapping stack of avatars with a max cap and an i18n-labelled +N overflow chip',
  category: 'display',
  clientJs: 'none',
  states: ['default'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'max',
      type: 'number',
      required: false,
      description: 'Cap the number of visible avatars',
    },
    {
      name: 'total',
      type: 'number',
      required: false,
      description: 'Override the total count used for the +N chip',
    },
    {
      name: 'spacing',
      description: 'Spacing between items.',
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'isGrid',
      description: 'When true, lays the avatars out in a grid instead of an overlapping stack.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: 'AvatarGroupLabels',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-text-muted',
    '--cascivo-space-2',
    '--cascivo-text-xs',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Basic',
      code: '<AvatarGroup><Avatar fallback="A" /><Avatar fallback="B" /><Avatar fallback="C" /></AvatarGroup>',
    },
    {
      title: 'With max',
      code: '<AvatarGroup max={3}>{users.map((u) => <Avatar key={u.id} src={u.src} alt={u.name} />)}</AvatarGroup>',
    },
    { title: 'Grid', code: '<AvatarGroup isGrid max={8}>{avatars}</AvatarGroup>' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['avatar'],
  tags: ['avatar', 'group', 'stack', 'overflow', 'display'],
  intent: {
    whenToUse: [
      'Showing several people compactly as an overlapping stack (collaborators, attendees, reviewers)',
      'Capping a long list of avatars with a +N overflow chip',
      'A facepile in a card header, table cell, or activity row',
    ],
    whenNotToUse: [
      'A single identity with a name — use User or Avatar',
      'A selectable list of people — use a list/menu with checkboxes',
    ],
    antiPatterns: [
      {
        bad: '<AvatarGroup>{hundredsOfAvatars}</AvatarGroup> with no max',
        good: '<AvatarGroup max={5} total={120}>{avatars}</AvatarGroup>',
        why: 'Without a max the row grows unbounded; a cap plus total keeps it compact and accurate',
      },
    ],
    related: [
      {
        name: 'Avatar',
        relationship: 'contains',
        reason: 'AvatarGroup arranges Avatar children and adds an overflow chip',
      },
      {
        name: 'User',
        relationship: 'alternative',
        reason: 'Use User for a single labelled identity row',
      },
    ],
    a11yRationale:
      'The stack is a labelled group; the +N chip carries an i18n-defaulted aria-label ("{count} more") so the hidden count is announced, not conveyed by the chip text alone',
    flexibility: [
      {
        area: 'spacing',
        level: 'flexible',
        note: 'Pick the overlap that fits the surrounding density',
      },
      {
        area: 'overflow label',
        level: 'strict',
        note: 'The +N label must come from i18n (builtin.avatarGroup.more or a labels override)',
      },
    ],
  },
}
